                  : 'text-slate-400 bg-slate-100'
              }`}>
                {activeFeaturesCount} {activeFeaturesCount === 1 ? 'ativo' : 'ativos'}
              </span>
              {openSections.holes ? (
                <ChevronUp className="w-4 h-4 text-slate-600" />
