                <ChevronDown className="w-4 h-4 text-slate-600" />
              )}
            </div>
          </button>

          {openSections.holes && (
            <div className="p-3.5 space-y-3 bg-white">
              {template.compatibleFeatures.length > 0 ? (
                <div className="space-y-2.5">
