@import "tailwindcss";

@layer base {
  :root {
    --font-sans: 'Inter', system-ui, -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    --font-heading: 'Barlow Condensed', 'Inter', system-ui, -apple-system, sans-serif;
    --font-mono: 'JetBrains Mono', 'IBM Plex Mono', Menlo, Consolas, monospace;
  }

  html, body {
    /* Evita rolagem horizontal acidental em telas estreitas (celular). */
    overflow-x: hidden;
    max-width: 100%;
  }

  body {
    font-family: var(--font-sans);
    background-color: #f8fafc;
    color: #0f172a;
    -webkit-font-smoothing: antialiased;
  }

  /* Foco visível consistente por teclado (acessibilidade). */
  :focus-visible {
    outline: 2px solid #FF3000;
    outline-offset: 2px;
    border-radius: 4px;
  }

  h1, h2, h3, h4, h5, h6, .font-heading {
    font-family: var(--font-heading);
    letter-spacing: -0.015em;
  }

  code, kbd, samp, pre, .font-mono {
    font-family: var(--font-mono);
    font-feature-settings: 'tnum' on, 'zero' on;
  }
}

/* Custom Scrollbar Clean Light */
