  width: 6px;
  height: 6px;
}
::-webkit-scrollbar-track {
  background: #f1f5f9;
}
::-webkit-scrollbar-thumb {
  background: #cbd5e1;
  border-radius: 3px;
}
::-webkit-scrollbar-thumb:hover {
  background: #FF3000;
}

/* Technical CAD Grid Pattern (Light Theme) */
.bg-cad-grid {
  background-size: 20px 20px;
  background-image: 
