}

/* CAD Viewport Sticky on Desktop with sufficient vertical space */
@media (min-width: 1024px) and (min-height: 700px) {
  .cad-viewport-sticky {
    position: sticky;
    top: 5rem;
    align-self: flex-start;
  }
}

/* ITEM 2.1: Sliders Interativos (WebKit & Firefox) */
.param-slider {
  -webkit-appearance: none;
  appearance: none;
  width: 100%;
  height: 4px;
  background: linear-gradient(to right, #94a3b8 0%, #94a3b8 var(--slider-pct, 0%), #e2e8f0 var(--slider-pct, 0%), #e2e8f0 100%);
  border-radius: 9999px;
  outline: none;
  cursor: pointer;
  transition: height 0.15s cubic-bezier(0.4, 0, 0.2, 1), background 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}

.param-slider:hover,
.param-slider:active {
  height: 6px;
  background: linear-gradient(to right, #FF3000 0%, #FF3000 var(--slider-pct, 0%), #cbd5e1 var(--slider-pct, 0%), #cbd5e1 100%);
}

/* WebKit Thumb */
.param-slider::-webkit-slider-thumb {
  -webkit-appearance: none;
  appearance: none;
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #64748b;
  border: 2px solid #ffffff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18);
