}

/* Firefox Thumb */
.param-slider::-moz-range-thumb {
  width: 12px;
  height: 12px;
  border-radius: 50%;
  background: #64748b;
  border: 2px solid #ffffff;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.18);
  cursor: grab;
  transition: transform 0.15s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.15s cubic-bezier(0.4, 0, 0.2, 1), box-shadow 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}

.param-slider:hover::-moz-range-thumb,
.param-slider:active::-moz-range-thumb {
  transform: scale(1.3);
  background: #FF3000;
  box-shadow: 0 0 0 3px rgba(255, 48, 0, 0.22), 0 2px 4px rgba(0, 0, 0, 0.2);
  cursor: grabbing;
}

.param-slider:focus-visible::-moz-range-thumb {
  box-shadow: 0 0 0 3px rgba(255, 48, 0, 0.35), 0 2px 4px rgba(0, 0, 0, 0.2);
}

/* Firefox Track & Progress */
.param-slider::-moz-range-track {
  height: 4px;
  background: #e2e8f0;
  border-radius: 9999px;
  transition: height 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}

.param-slider:hover::-moz-range-track,
.param-slider:active::-moz-range-track {
