  transition: height 0.15s cubic-bezier(0.4, 0, 0.2, 1), background-color 0.15s cubic-bezier(0.4, 0, 0.2, 1);
}

.param-slider:hover::-moz-range-progress,
.param-slider:active::-moz-range-progress {
  height: 6px;
  background: #FF3000;
}

/* Toque (celular/touch): trilho e thumb maiores para facilitar o arraste com o dedo. */
@media (pointer: coarse) {
  /* Alvos de toque confortaveis (>= 44px) em telas de toque, sem alterar o visual no desktop. */
  .tap-target {
